CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,name text NOT NULL,is_admin boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,expires_at timestamptz NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE sites(id text PRIMARY KEY,name text NOT NULL,domain text NOT NULL,timezone text NOT NULL DEFAULT 'Asia/Shanghai',privacy_mode text NOT NULL DEFAULT 'standard' CHECK(privacy_mode IN('standard','daily_salt')),salt_secret text NOT NULL,retention_days integer NOT NULL DEFAULT 365 CHECK(retention_days BETWEEN 1 AND 3650),tags jsonb NOT NULL DEFAULT '[]',config jsonb NOT NULL DEFAULT '{}',last_event_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE site_members(site_id text REFERENCES sites ON DELETE CASCADE,user_id uuid REFERENCES users ON DELETE CASCADE,role text NOT NULL CHECK(role IN('owner','admin','analyst','viewer')),PRIMARY KEY(site_id,user_id));
CREATE TABLE events(site_id text NOT NULL REFERENCES sites ON DELETE CASCADE,event_id uuid NOT NULL,ts timestamptz NOT NULL,visitor_id text NOT NULL,page_id uuid NOT NULL,type text NOT NULL,path text NOT NULL,payload jsonb NOT NULL,dimensions jsonb NOT NULL DEFAULT '{}',is_bot boolean NOT NULL DEFAULT false,PRIMARY KEY(site_id,event_id,ts)) PARTITION BY RANGE(ts);
CREATE TABLE events_default PARTITION OF events DEFAULT;
CREATE INDEX events_site_time ON events(site_id,ts);
CREATE INDEX events_visitor_time ON events(site_id,visitor_id,ts);
CREATE TABLE event_data(site_id text NOT NULL,event_id uuid NOT NULL,ts timestamptz NOT NULL,data_key text NOT NULL,data_type char(1) NOT NULL CHECK(data_type IN('s','n','b','d')),string_value text,number_value numeric,boolean_value boolean,date_value timestamptz,PRIMARY KEY(site_id,event_id,ts,data_key),FOREIGN KEY(site_id,event_id,ts) REFERENCES events ON DELETE CASCADE) PARTITION BY RANGE(ts);
CREATE TABLE event_data_default PARTITION OF event_data DEFAULT;
CREATE TABLE event_keys(site_id text REFERENCES sites ON DELETE CASCADE,event_id uuid NOT NULL,hash text NOT NULL,ts timestamptz NOT NULL,visitor_id text NOT NULL,PRIMARY KEY(site_id,event_id));
CREATE TABLE identity_map(site_id text REFERENCES sites ON DELETE CASCADE,visitor_id text NOT NULL,user_id text NOT NULL,created_at timestamptz DEFAULT now(),PRIMARY KEY(site_id,visitor_id));
CREATE INDEX identity_user ON identity_map(site_id,user_id);
CREATE TABLE visitor_first_seen(site_id text REFERENCES sites ON DELETE CASCADE,visitor_id text NOT NULL,first_date date NOT NULL,PRIMARY KEY(site_id,visitor_id));
CREATE TABLE tombstones(site_id text NOT NULL,visitor_id text NOT NULL,user_id text,deleted_at timestamptz NOT NULL DEFAULT now(),source text NOT NULL DEFAULT 'request',PRIMARY KEY(site_id,visitor_id));
CREATE TABLE audit_logs(id bigserial PRIMARY KEY,site_id text,actor_id uuid,action text NOT NULL,target jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_site ON audit_logs(site_id,created_at);
CREATE TABLE aggregation_state(site_id text PRIMARY KEY REFERENCES sites ON DELETE CASCADE,generation bigint NOT NULL DEFAULT 0,processed_generation bigint NOT NULL DEFAULT 0,lease_owner uuid,lease_until timestamptz,watermark timestamptz,epoch uuid NOT NULL DEFAULT gen_random_uuid());
CREATE TABLE outbox(id bigserial PRIMARY KEY,site_id text REFERENCES sites ON DELETE CASCADE,event_id uuid,ts timestamptz,visitor_id text,status text NOT NULL DEFAULT 'queued',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_status ON outbox(status,id);
CREATE TABLE bot_counts(site_id text REFERENCES sites ON DELETE CASCADE,day date NOT NULL,category text NOT NULL,count bigint NOT NULL DEFAULT 0,PRIMARY KEY(site_id,day,category));
